// Gradle build for the Java bindings of nova-ta generated by uniffi-bindgen-java.
// The bindings use the JDK Foreign Function & Memory API: JDK 22+ and
// `--enable-native-access=ALL-UNNAMED` at run time. The native library is bundled
// under src/main/resources/<os-arch>/ by `cargo xtask build -t java`.
// The version is kept in sync with Cargo.toml by `cargo xtask check` / `cargo xtask bump`.

plugins {
    `java-library`
    `maven-publish`
}

group = "io.github.rick29"
version = "0.1.2"

repositories {
    mavenCentral()
}

java {
    toolchain {
        languageVersion.set(JavaLanguageVersion.of(22))
    }
}

tasks.withType<JavaExec>().configureEach {
    jvmArgs("--enable-native-access=ALL-UNNAMED")
}

tasks.withType<Test>().configureEach {
    jvmArgs("--enable-native-access=ALL-UNNAMED")
}

publishing {
    publications {
        create<MavenPublication>("maven") {
            artifactId = "nova-ta-java"
            from(components["java"])
        }
    }
}
